<script setup lang="ts">
import BusinessStatus from '../components/BusinessStatus.vue';
import {businessRowClass} from '../business-status';
import { ref,reactive,computed,watch,onMounted,onBeforeUnmount } from 'vue';
import { useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate } from 'vue-router';
import { ElMessage,ElMessageBox } from 'element-plus';
import { api,get,message } from '../api';
import { useAuth } from '../stores/auth';
import Icon from '../components/Icon.vue';
import GrainImage from '../components/GrainImage.vue';
import PointPicker from '../components/PointPicker.vue';
import { supplyCompany,supplyRange,supplyLoading,supplyQuotes } from '../supply-format';
const route=useRoute(),router=useRouter(),auth=useAuth();
const demand=computed(()=>route.meta.kind==='demand'),kind=computed(()=>demand.value?'demand':'supply'),name=computed(()=>demand.value?'运输需求':'运输供给');
const endpoint=computed(()=>demand.value?'/transport-demands':'/transport-supplies');
const canWrite=computed(()=>auth.can(`${kind.value}:write`)&&auth.user?.businessEntity.type===(demand.value?'TRADER':'CARRIER'));
const canPublish=computed(()=>canWrite.value&&auth.can(`${kind.value}:publish`));
const options=ref<any>({grains:[],modes:[],carriers:[],regions:[],nodes:[]}),rows=ref<any[]>([]),total=ref(0),loading=ref(false),error=ref(''),selected=ref<any[]>([]);
const query=reactive({q:'',status:'',grainId:'',modeId:'',origin:'',destination:'',page:1,pageSize:10,order:'desc'});
const statusNames:Record<string,string>={DRAFT:'草稿',PUBLISHED:'已发布',PAUSED:'已暂停',EXPIRED:'已失效',CANCELLED:'已取消',ACTIVE:'响应中',CLOSED:'已关闭'};
const matchNames:Record<string,string>={UNMATCHED:'未发布匹配',WAITING:'待报价',BIDDING:'报价中',NEGOTIATING:'议价中',PENDING_CONFIRM:'待确认承运',PARTIAL:'部分匹配',MATCHED:'匹配完成',REMATCH:'待重新匹配'};
const statuses=computed(()=>demand.value?['DRAFT','PUBLISHED','CANCELLED']:['DRAFT','PUBLISHED','PAUSED','EXPIRED']);
const date=(v?:string)=>v?new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
const tonnes=(value:unknown)=>{const n=Number(value);return Number.isFinite(n)?n.toLocaleString('zh-CN',{minimumFractionDigits:1,maximumFractionDigits:1}):'—';};
const fullDate=(v?:string)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—';
const label=(value:string)=>({BULK:'散装',CONTAINER:'集装箱',BALANCED:'综合均衡',COST:'成本优先',TIME:'时效优先',VEHICLE:'车辆',RAIL:'铁路运力',VESSEL:'船舶',COMBINED:'联运资源',PER_TON:'元/吨',PER_VEHICLE:'元/车',PER_CONTAINER:'元/箱',TOTAL:'元/单',PUBLIC:'公开发布',DIRECTED:'邀约议价'} as Record<string,string>)[value]||value||'—';
const grainCode=(row:any)=>demand.value?(row.orderItem?.grain.code||row.grain?.code):row.grains?.[0]?.grain.code;
const photo=(row:any)=>row.files?.find((f:any)=>f.kind==='PHOTO')?.id;
const editable=(row:any)=>canWrite.value&&(demand.value?row.status==='DRAFT':['DRAFT','PAUSED','EXPIRED'].includes(row.status));
let request=0;
async function load(){const version=++request;loading.value=true;error.value='';selected.value=[];try{const data=await get(endpoint.value,query);if(version===request){rows.value=data.items;total.value=data.total;}}catch(e){if(version===request)error.value=message(e);}finally{if(version===request)loading.value=false;}}
async function search(){query.page=1;await router.replace({query:{...query}});await load();}
function reset(){Object.assign(query,{q:'',status:'',grainId:'',modeId:'',origin:'',destination:'',page:1,pageSize:10,order:'desc'});search();}
const detail=ref<any>(null),detailOpen=ref(false),detailLoading=ref(false),detailError=ref(''),history=ref<any[]>([]);
async function openDetail(id:string,updateUrl=true){detailOpen.value=true;detailLoading.value=true;detailError.value='';detail.value=null;history.value=[];try{const [row,log]=await Promise.all([get(`${endpoint.value}/${id}`),get(`${endpoint.value}/${id}/history`)]);detail.value=row;history.value=log;if(updateUrl)await router.replace({query:{...route.query,id}});}catch(e){detailError.value=message(e);}finally{detailLoading.value=false;}}
function closeDetail(){if(!['demand','supply'].includes(String(route.meta.kind)))return;const q={...route.query};delete q.id;router.replace({query:q});}
const editor=ref(false),editingId=ref(''),saving=ref(false),formError=ref(''),formRef=ref<any>(),form=reactive<any>({});let snapshot='';
const chosenOrder=ref<any>(null),orderOpen=ref(false),orderRows=ref<any[]>([]),orderTotal=ref(0),orderLoading=ref(false),orderError=ref(''),orderQuery=reactive({q:'',page:1,pageSize:10});
const cityOptions=computed(()=>options.value.regions.map((province:any)=>({...province,children:province.children.map(({children,...city}:any)=>({...city,label:['市辖区','县'].includes(city.label)?province.label:city.label}))})));
const routeRegion=(row:any,key:string)=>{const region=row[key+'Region'];if(!region)return row[key+'Address']||'—';return demand.value?region.split(' / ').slice(1).join(' · '):region.split(' / ').join(' · ');};
const originalQuantity=ref(0),originalOrderId=ref('');
const standaloneDemand=computed(()=>demand.value&&!form.orderItemId);
const ownOrderQuantity=computed(()=>chosenOrder.value?.id===originalOrderId.value?originalQuantity.value:0);
const otherBatchQuantity=computed(()=>Math.max(0,(chosenOrder.value?.reservedQuantity||0)-ownOrderQuantity.value));
const availableQuantity=computed(()=>standaloneDemand.value?1000000:chosenOrder.value?Math.max(0,Math.round((chosenOrder.value.quantity-otherBatchQuantity.value)*1000)/1000):0);
const quantityHint=computed(()=>standaloneDemand.value?'直接填写本次运输数量，无需关联交易订单。':!chosenOrder.value?'请重新选择交易订单明细':`订单成交 ${tonnes(chosenOrder.value.quantity)} 吨，其他批次已占用 ${tonnes(otherBatchQuantity.value)} 吨，本需求最多 ${tonnes(availableQuantity.value)} 吨。${Number(form.quantity)>availableQuantity.value?'本次数量超出可用额度，请减少运输数量。':`本次填写 ${tonnes(Number(form.quantity)||0)} 吨，保存后剩余 ${tonnes(Math.max(0,availableQuantity.value-(Number(form.quantity)||0)))} 吨。`}`);
const demandTitle=(row:any)=>`${row.orderItem?.grain?.label||row.grain?.label||row.orderItem?.cargoName||row.cargoName||'粮食'} ${tonnes(row.quantity)} 吨`;
async function loadOrders(){orderLoading.value=true;orderError.value='';try{const data=await get('/trade-orders',orderQuery);orderRows.value=data.items;orderTotal.value=data.total;}catch(e){orderError.value=message(e);}finally{orderLoading.value=false;}}
async function pickOrder(){orderOpen.value=true;await loadOrders();}
function selectOrder(row:any){chosenOrder.value=row;form.orderItemId=row.id;form.grainId=row.grainId;form.cargoName=row.cargoName;form.specification=row.specification;form.quantity=Math.floor((row.remainingQuantity+(row.id===originalOrderId.value?originalQuantity.value:0)+Number.EPSILON)*10)/10;if(row.tradeOrder.shipperContact)form.contact=row.tradeOrder.shipperContact;if(row.tradeOrder.shipperPhone)form.phone=row.tradeOrder.shipperPhone;if(row.pickupAddress){form.originAddress=row.pickupAddress;form.originCodes=row.pickupCodes||[];}orderOpen.value=false;formRef.value?.clearValidate(['orderItemId','grainId','specification','quantity','originAddress']);}
function unlinkOrder(){chosenOrder.value=null;form.orderItemId='';formRef.value?.clearValidate(['orderItemId','grainId','specification','quantity']);}
function selectGrain(id:string){form.cargoName=options.value.grains.find((g:any)=>g.id===id)?.label||'';}
watch(()=>form.originAddress,()=>{if(demand.value){form.originCodes=[];form.originPoint=null;}},{flush:'sync'});
watch(()=>form.destinationAddress,()=>{if(demand.value){form.destinationCodes=[];form.destinationPoint=null;}},{flush:'sync'});
function selectLocation(key:'origin'|'destination',point:any){form[`${key}Address`]=point.matchedAddress||point.name;form[`${key}Point`]=point;formRef.value?.clearValidate([`${key}Address`,`${key}Point`]);}
const draftKey=()=>`transport-demand-draft:${auth.user?.id}:${editingId.value||'new'}`;
function clearLocalDraft(){if(demand.value)try{localStorage.removeItem(draftKey());}catch{/* Storage can be unavailable in a restricted browser. */}}
watch(form,()=>{if(!demand.value||!editor.value||saving.value||snapshot===JSON.stringify(form))return;try{localStorage.setItem(draftKey(),JSON.stringify({form:{...form},orderNo:chosenOrder.value?.tradeOrder.businessNo||'',savedAt:Date.now()}));}catch{/* Keep the current editor usable when storage is full. */}},{deep:true});
async function restoreLocalDraft(){
  let draft:any;try{draft=JSON.parse(localStorage.getItem(draftKey())||'null');}catch{return;}
  if(!draft?.form||Date.now()-draft.savedAt>7*86400000||draft.form.version!==form.version){clearLocalDraft();return;}
  try{await ElMessageBox.confirm('发现此需求未保存的填写内容，是否恢复？','恢复填写内容',{confirmButtonText:'恢复',cancelButtonText:'重新填写'});}catch{clearLocalDraft();return;}
  const restoredOrder=draft.form.orderItemId?await get('/trade-orders',{q:draft.orderNo||'',page:1,pageSize:100}).then(data=>data.items.find((item:any)=>item.id===draft.form.orderItemId)).catch(()=>null):null;
  if(draft.form.orderItemId&&!restoredOrder){ElMessage.warning('关联订单已不可用，请重新选择。');draft.form.orderItemId='';}
  Object.assign(form,draft.form);form.originCodes=draft.form.originCodes||[];form.destinationCodes=draft.form.destinationCodes||[];form.originPoint=draft.form.originPoint||null;form.destinationPoint=draft.form.destinationPoint||null;chosenOrder.value=restoredOrder;formRef.value?.clearValidate();
}
async function edit(row?:any){formError.value='';editingId.value=row?.id||'';chosenOrder.value=null;Object.keys(form).forEach(k=>delete form[k]);
  if(row)try{row=await get(`${endpoint.value}/${row.id}`);}catch(e){ElMessage.error(message(e));return;}
  originalQuantity.value=demand.value&&row?row.quantity:0;originalOrderId.value=demand.value?row?.orderItemId||'':'';
  const common={originAddress:'',destinationAddress:'',originPoint:null,destinationPoint:null,contact:'',phone:'',notes:''};
  const defaults=demand.value?{...common,orderItemId:'',grainId:'',cargoName:'',specification:'',quantity:1,departureAt:'',arrivalAt:'',modeIds:[],loadingType:'BULK',originCodes:[],destinationCodes:[]}:{contact:'',phone:'',notes:'',originCodes:[],destinationCodes:[],modeId:'',minQuantity:1,maxQuantity:1000,resourceDescription:'',grainIds:[],loadingType:'BULK',bulkPrice:null,container20Price:null,container40Price:null,capabilities:''};
  Object.assign(form,defaults);if(row){for(const key of Object.keys(defaults))form[key]=row[key]??(defaults as any)[key];form.version=row.version;if(demand.value&&row.orderItem){const item=row.orderItem;form.grainId=item.grainId;form.cargoName=item.cargoName;form.specification=item.specification;chosenOrder.value={...item,quantity:item.quantityKg/1000,reservedQuantity:item.reservedKg/1000,remainingQuantity:(item.quantityKg-item.reservedKg)/1000};}}
  if(!demand.value&&row){form.originCodes=row.originCodes.slice(0,2);form.destinationCodes=row.destinationCodes.slice(0,2);form.minQuantity=row.minQuantity??row.capacity;form.maxQuantity=row.maxQuantity??row.capacity;}
  snapshot=JSON.stringify(form);editor.value=true;formRef.value?.clearValidate();if(demand.value)await restoreLocalDraft();
}
const departureClock=ref(new Date()),departureDefaultTime=ref(new Date(Date.now()+60000));
let departureTimer:ReturnType<typeof setInterval>|undefined;
function departureVisible(visible:boolean){
  clearInterval(departureTimer);departureTimer=undefined;departureClock.value=new Date();
  if(visible){departureDefaultTime.value=new Date(Date.now()+60000);departureTimer=setInterval(()=>departureClock.value=new Date(),1000);}
}
onBeforeUnmount(()=>clearInterval(departureTimer));
const disabledDepartureDate=(day:Date)=>day.getTime()<new Date(departureClock.value).setHours(0,0,0,0);
const departureIsToday=()=>!form.departureAt||new Date(form.departureAt).toDateString()===departureClock.value.toDateString();
const before=(limit:number)=>Array.from({length:limit},(_,i)=>i);
const disabledDepartureHours=()=>departureIsToday()?before(departureClock.value.getHours()):[];
const disabledDepartureMinutes=(hour:number)=>departureIsToday()&&hour===departureClock.value.getHours()?before(departureClock.value.getMinutes()):[];
const disabledDepartureSeconds=(hour:number,minute:number)=>departureIsToday()&&hour===departureClock.value.getHours()&&minute===departureClock.value.getMinutes()?before(departureClock.value.getSeconds()+1):[];
const required=(text:string)=>[{required:true,message:`请填写${text}`,trigger:'blur'}];
const pointRule=(label:string)=>[{required:true,validator:(_rule:any,value:any,done:any)=>done(!value||!Number.isFinite(value.lng)||!Number.isFinite(value.lat)||value.matchKind==='APPROXIMATE'?new Error(`请在地图选择${label}的实际装卸位置`):undefined),trigger:'change'}];
const rules=computed(()=>({...Object.fromEntries((demand.value?['originAddress','destinationAddress','contact','phone']:['contact','phone']).map(k=>[k,required(({originAddress:'起运详细地址',destinationAddress:'目的详细地址',contact:'联系人',phone:'联系电话'} as any)[k])])),...(demand.value?{originPoint:pointRule('起运地'),destinationPoint:pointRule('目的地'),grainId:standaloneDemand.value?required('粮食品种'):[],specification:standaloneDemand.value?required('货物规格'):[],quantity:[...required('运输数量'),{validator:(_rule:any,value:any,done:any)=>{const n=Number(value);done(!Number.isFinite(n)||n<=0?new Error('运输数量须大于 0'):n>availableQuantity.value?new Error(standaloneDemand.value?'运输数量不能超过 1000000 吨':`分批运输不能超过订单成交量，本需求最多 ${tonnes(availableQuantity.value)} 吨`):undefined);},trigger:['blur','change']}],departureAt:[...required('计划发运时间'),{validator:(_rule:any,value:any,done:any)=>done(value&&new Date(value).getTime()<=Date.now()?new Error('计划发运时间必须晚于当前时间'):undefined),trigger:['blur','change']}],arrivalAt:[...required('要求到达时间'),{validator:(_rule:any,value:any,done:any)=>done(value&&form.departureAt&&new Date(value)<=new Date(form.departureAt)?new Error('要求到达时间必须晚于计划发运时间'):undefined),trigger:['blur','change']}]}:{originCodes:required('起运地区'),destinationCodes:required('目的地区'),modeId:required('运输方式'),minQuantity:[...required('承运量下限'),{validator:(_rule:any,value:any,done:any)=>done(value>form.maxQuantity?new Error('可承运数量下限不能超过上限'):undefined),trigger:['blur','change']}],maxQuantity:[...required('承运量上限'),{validator:(_rule:any,value:any,done:any)=>done(value<form.minQuantity?new Error('可承运数量上限不能小于下限'):undefined),trigger:['blur','change']}],loadingType:required('装载形式'),...(form.loadingType==='CONTAINER'?{container20Price:required('20GP 报价'),container40Price:required('40GP 报价')}:{bulkPrice:required('散货报价')})})}));
async function discard(){if(saving.value)return false;if(editor.value&&snapshot!==JSON.stringify(form))try{await ElMessageBox.confirm('未保存的运输信息将丢失。','放弃修改？',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑',type:'warning'});}catch{return false;}if(editor.value)clearLocalDraft();editor.value=false;return true;}
onBeforeRouteLeave(discard);onBeforeRouteUpdate(to=>to.meta.kind!==route.meta.kind?discard():true);
function beforeUnload(e:BeforeUnloadEvent){if(editor.value&&snapshot!==JSON.stringify(form)){e.preventDefault();e.returnValue='';}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload));onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload));
async function save(){formError.value='';if(!await formRef.value.validate().catch(()=>false))return;saving.value=true;try{const payload={...form};if(standaloneDemand.value)delete payload.orderItemId;if(demand.value){for(const key of ['originCodes','destinationCodes'])if(payload[key]?.length!==3)delete payload[key];}if(!demand.value){if(payload.loadingType==='BULK'){delete payload.container20Price;delete payload.container40Price;}else delete payload.bulkPrice;}const result=editingId.value?await api.put(`${endpoint.value}/${editingId.value}`,payload):await api.post(endpoint.value,payload);clearLocalDraft();editor.value=false;ElMessage.success('已保存草稿');await load();await openDetail(result.data.data.id);}catch(e){formError.value=message(e);}finally{saving.value=false;}}
const publicationOpen=ref(false),publicationRow=ref<any>(null),publicationError=ref(''),publication=reactive<any>({mode:'PUBLIC',targetCarrierIds:[],deadline:'',quoteType:'TOTAL',allowPartial:false,budgetPublic:false,contactPublic:false,notes:''});
function publish(row:any){if(!demand.value){action(row,'publish');return;}publicationRow.value=row;publicationError.value='';Object.assign(publication,{mode:'PUBLIC',targetCarrierIds:[],deadline:'',quoteType:'TOTAL',allowPartial:false,budgetPublic:false,contactPublic:false,notes:''});publicationOpen.value=true;}
async function confirmPublish(){if(!publication.deadline||publication.mode==='DIRECTED'&&!publication.targetCarrierIds.length){publicationError.value='请选择响应截止时间和发布对象';return;}saving.value=true;publicationError.value='';try{const payload={...publication,version:publicationRow.value.version};if(payload.mode==='PUBLIC')delete payload.targetCarrierIds;await api.post(`${endpoint.value}/${publicationRow.value.id}/publish`,payload);publicationOpen.value=false;ElMessage.success('需求已发布');await load();if(detailOpen.value)await openDetail(publicationRow.value.id);}catch(e){publicationError.value=message(e);}finally{saving.value=false;}}
const actionNames:Record<string,string>={publish:'发布',withdraw:'撤回',cancel:'取消需求',delete:'删除',pause:'暂停',expire:'终止供给'};
async function action(row:any,operation:string){try{await ElMessageBox.confirm(`${actionNames[operation]}“${row.name}”？${demand.value&&row.orderItemId?(['cancel','delete'].includes(operation)?'该需求占用的订单数量将释放。':operation==='withdraw'?'撤回后可编辑，订单数量继续保留。':''):(operation==='publish'?'发布后可在供需匹配中被查看。':'')}`,`${actionNames[operation]}确认`,{confirmButtonText:`确认${actionNames[operation]}`,cancelButtonText:'返回',type:'warning'});saving.value=true;await api.post(`${endpoint.value}/${row.id}/${operation}`,{version:row.version});ElMessage.success('操作成功');await load();if(detailOpen.value){if(operation==='delete'){detailOpen.value=false;closeDetail();}else await openDetail(row.id);}}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(message(e));}finally{saving.value=false;}}
const fileInput=ref<HTMLInputElement>(),fileKind=ref('DOCUMENT');
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;if(file.size>10*1024*1024){ElMessage.error('附件不能超过10MB');input.value='';return;}saving.value=true;const data=new FormData();data.append('kind',fileKind.value);data.append('file',file);try{await api.post(`/transport-files/${kind.value}/${detail.value.id}`,data);ElMessage.success('附件已上传');await openDetail(detail.value.id);await load();}catch(e){ElMessage.error(message(e));}finally{saving.value=false;input.value='';}}
async function download(file:any){try{const response=await api.get(`/transport-files/${file.id}`,{responseType:'blob'});const url=URL.createObjectURL(response.data);const a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){ElMessage.error(message(e));}}
async function removeFile(file:any){try{await ElMessageBox.confirm(`移除附件“${file.name}”？`,'移除附件',{confirmButtonText:'移除',cancelButtonText:'保留',type:'warning'});saving.value=true;await api.delete(`/transport-files/${file.id}`);await openDetail(detail.value.id);await load();}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(message(e));}finally{saving.value=false;}}
function exportSelected(){const escape=(v:any)=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const data=demand.value?[['业务编号','货类 / 数量','起运地','目的地','数量（吨）','状态'],...selected.value.map(r=>[r.businessNo,demandTitle(r),r.originRegion,r.destinationRegion,r.quantity,statusNames[r.status]])]:[['运输企业','运输方式','起运地区','目的地区','可承运数量范围','适运粮种','装载形式','报价','状态'],...selected.value.map(r=>[supplyCompany(r),r.mode.label,r.originRegion,r.destinationRegion,supplyRange(r),r.grains.map((g:any)=>g.grain.label).join('、')||'不限',supplyLoading(r),supplyQuotes(r).join('；'),statusNames[r.status]])];const url=URL.createObjectURL(new Blob(['\uFEFF'+data.map(r=>r.map(escape).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`${name.value}.csv`;a.click();URL.revokeObjectURL(url);}
watch(kind,async()=>{if(!['demand','supply'].includes(String(route.meta.kind)))return;detailOpen.value=false;editor.value=false;publicationOpen.value=false;Object.assign(query,{q:String(route.query.q||''),status:String(route.query.status||''),grainId:String(route.query.grainId||''),modeId:String(route.query.modeId||''),origin:String(route.query.origin||''),destination:String(route.query.destination||''),page:Math.max(1,Number(route.query.page)||1),pageSize:10,order:'desc'});try{options.value=await get('/transport-options');}catch(e){error.value=message(e);return;}await load();if(route.query.id)await openDetail(String(route.query.id),false);if(route.query.create==="1"&&canWrite.value){const nextQuery={...route.query};delete nextQuery.create;await router.replace({query:nextQuery});await edit();}},{immediate:true});
</script>

<template>

<el-form class="filter-panel transport-filters" inline @submit.prevent="search">
<el-form-item label="关键词"><el-input v-model="query.q" :placeholder="demand?'粮食品种 / 编号':'企业名称 / 编号'" aria-label="搜索关键词" clearable/></el-form-item>
<el-form-item label="状态"><el-select v-model="query.status" clearable placeholder="全部状态" aria-label="状态筛选"><el-option v-for="s in statuses" :key="s" :label="statusNames[s]" :value="s"/></el-select></el-form-item>
<el-form-item label="粮食品种"><el-select v-model="query.grainId" clearable placeholder="全部品种" aria-label="粮食品种筛选"><el-option v-for="g in options.grains" :key="g.id" :value="g.id" :label="g.label"/></el-select></el-form-item>
<el-form-item label="运输方式"><el-select v-model="query.modeId" clearable placeholder="全部方式" aria-label="运输方式筛选"><el-option v-for="m in options.modes" :key="m.id" :value="m.id" :label="m.label"/></el-select></el-form-item>
<el-form-item label="起运地"><el-input v-model="query.origin" :placeholder="demand?'省 / 市 / 区':'省 / 市'" aria-label="起运地筛选" clearable/></el-form-item><el-form-item label="目的地"><el-input v-model="query.destination" :placeholder="demand?'省 / 市 / 区':'省 / 市'" aria-label="目的地筛选" clearable/></el-form-item>
<el-form-item class="filter-actions"><el-button type="primary" plain native-type="submit">搜索</el-button><el-button @click="reset">重置</el-button></el-form-item>
</el-form>
<section class="table-panel"><div class="list-toolbar"><div><strong>{{name}}列表</strong><span>共 <b>{{total}}</b> 条</span></div><div><el-select v-model="query.order" class="transport-sort" aria-label="排序" @change="search"><el-option label="最新创建" value="desc"/><el-option label="最早创建" value="asc"/></el-select><el-button v-if="canWrite" type="primary" @click="edit()"><Icon name="plus" :size="16"/>新建{{name}}</el-button></div></div>
<div v-if="selected.length" class="bulk-bar"><span>已选择 {{selected.length}} 项</span><el-button size="small" @click="exportSelected">导出所选</el-button></div>
<el-alert v-if="error" :title="error" type="error" show-icon :closable="false"><el-button @click="load">重新加载</el-button></el-alert>
<el-table v-else :row-class-name="businessRowClass" :data="rows" v-loading="loading" row-key="id" @selection-change="selected=$event" :empty-text="query.q||query.status||query.grainId||query.modeId||query.origin||query.destination?'没有符合条件的记录，请调整筛选条件':`暂无${name}，${canWrite?'点击右上方按钮新建':'发布后将在这里显示'}`">
<el-table-column type="selection" width="44"/>
<el-table-column :label="demand?'货类 / 数量':'运输企业'" :min-width="demand?250:205"><template #default="{row}"><div class="transport-identity"><GrainImage :code="grainCode(row)" :photo="photo(row)"/><div><button class="text-link row-title" @click="openDetail(row.id)">{{demand?demandTitle(row):supplyCompany(row)}}</button></div></div></template></el-table-column>
<el-table-column label="运输线路" :min-width="demand?230:400"><template #default="{row}"><template v-if="demand"><div class="route-cell"><span class="route-marker">起</span>{{routeRegion(row,'origin')}}</div><div class="route-cell"><span class="route-marker arrival">终</span>{{routeRegion(row,'destination')}}</div></template><div v-else class="supply-route-line"><span class="supply-route-endpoint" :title="routeRegion(row,'origin')">{{routeRegion(row,'origin')}}</span><Icon name="arrow" :size="20"/><span class="supply-route-endpoint" :title="routeRegion(row,'destination')">{{routeRegion(row,'destination')}}</span></div></template></el-table-column>
<el-table-column v-if="!demand" label="适运粮种" min-width="110"><template #default="{row}">{{row.grains.map((g:any)=>g.grain.label).join('、')||'不限'}}</template></el-table-column>
<el-table-column v-if="!demand" label="装载形式 / 报价" min-width="190"><template #default="{row}"><strong>{{supplyLoading(row)}}</strong><small v-for="price in supplyQuotes(row)" :key="price" class="cell-note">{{price}}</small></template></el-table-column>
<el-table-column v-if="demand" label="计划发运时间" min-width="145"><template #default="{row}">{{date(row.departureAt)}}</template></el-table-column>
<el-table-column v-if="demand" label="要求到达时间" min-width="145"><template #default="{row}">{{date(row.arrivalAt)}}</template></el-table-column>
<el-table-column label="状态" :width="demand?155:115"><template #default="{row}"><BusinessStatus :status="row.status" :label="statusNames[row.status]" compact/><div v-if="demand" class="cell-note"><BusinessStatus :status="row.matchStage" :label="matchNames[row.matchStage]||'未匹配'" compact/></div><small v-if="demand&&row.matchedKg" class="cell-note">已落实 {{row.matchedKg/1000}} 吨</small></template></el-table-column>
<el-table-column label="操作" fixed="right" width="160"><template #default="{row}"><el-button link type="primary" @click="openDetail(row.id)">详情</el-button><el-button v-if="editable(row)" link type="primary" @click="edit(row)">编辑</el-button><el-button v-if="canPublish&&['DRAFT',...(!demand?['PAUSED']:[])].includes(row.status)" link type="primary" @click="publish(row)">发布</el-button></template></el-table-column>
</el-table><div class="pagination"><el-pagination v-model:current-page="query.page" v-model:page-size="query.pageSize" :total="total" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next" @change="load"/></div></section>

<el-drawer v-model="editor" :title="(editingId?'编辑':'新建')+name" size="min(780px, 100vw)" :close-on-click-modal="false" :before-close="async(done:any)=>{if(await discard())done();}">
<el-alert v-if="formError" :title="formError" type="error" :closable="false" show-icon class="transport-alert"/>
<el-form ref="formRef" :model="form" :rules="rules" :validate-on-rule-change="false" label-position="top" class="transport-form" :disabled="saving" @submit.prevent="save">
<template v-if="demand">
<h3>01 · 货物信息</h3>
<el-form-item label="交易订单（选填）"><div class="order-actions"><el-button @click="pickOrder">{{chosenOrder?'更换交易订单':'选择交易订单'}}</el-button><el-button v-if="chosenOrder" link type="primary" @click="unlinkOrder">取消关联，手动填写</el-button></div><p class="form-hint">可直接填写运输需求；选择订单后带入货物、可运输数量、提货地址和已有联系人信息。</p>
<div v-if="chosenOrder" class="order-facts"><GrainImage :code="chosenOrder.grain.code"/><div><strong>{{chosenOrder.tradeOrder.businessNo}} · {{chosenOrder.cargoName}}</strong><p>货物规格：{{chosenOrder.specification}}<span v-if="chosenOrder.tradeOrder.recipient"> · 收货方：{{chosenOrder.tradeOrder.recipient}}</span></p><p v-if="chosenOrder.pickupAddress">提货地址：{{chosenOrder.pickupAddress}}</p><p>订单 {{tonnes(chosenOrder.quantity)}} 吨 · 已占用 {{tonnes(chosenOrder.reservedQuantity)}} 吨 · <b>剩余 {{tonnes(chosenOrder.remainingQuantity)}} 吨</b></p><small v-if="ownOrderQuantity">本需求当前占用 {{tonnes(ownOrderQuantity)}} 吨，编辑上限已加回这部分数量。</small></div></div></el-form-item>
<div v-if="standaloneDemand" class="form-two"><el-form-item label="粮食品种" prop="grainId"><el-select v-model="form.grainId" filterable placeholder="请选择粮食品种" @change="selectGrain"><el-option v-for="g in options.grains" :key="g.id" :label="g.label" :value="g.id"/></el-select></el-form-item><el-form-item label="货物规格" prop="specification"><el-input v-model="form.specification" maxlength="100" placeholder="等级、水分、包装等要求"/></el-form-item></div>
</template>
<h3>{{demand?'02':'01'}} · {{demand?'运输条件':'运力信息'}}</h3>
<el-form-item v-if="!demand" label="运输企业名称"><el-input :model-value="auth.user?.businessEntity.name" readonly/></el-form-item>
<div class="form-two"><el-form-item v-if="demand" label="运输数量（吨）" prop="quantity"><el-input-number v-model="form.quantity" :min="0.1" :max="Math.max(.1,Math.floor((availableQuantity+Number.EPSILON)*10)/10)" :disabled="availableQuantity<=0" :precision="1" :step=".1" controls-position="right"/></el-form-item><el-form-item v-if="demand" label="装载形式"><el-select v-model="form.loadingType"><el-option label="散装" value="BULK"/><el-option label="集装箱" value="CONTAINER"/></el-select></el-form-item><template v-else><el-form-item label="运输方式" prop="modeId"><el-select v-model="form.modeId"><el-option v-for="m in options.modes" :key="m.id" :label="m.label" :value="m.id"/></el-select></el-form-item><el-form-item label="可承运数量范围（吨）" required><div class="capacity-range"><el-form-item prop="minQuantity"><el-input-number v-model="form.minQuantity" aria-label="可承运数量下限（吨）" :min=".1" :max="1000000" :precision="1" :step=".1" controls-position="right"/></el-form-item><span>—</span><el-form-item prop="maxQuantity"><el-input-number v-model="form.maxQuantity" aria-label="可承运数量上限（吨）" :min=".1" :max="1000000" :precision="1" :step=".1" controls-position="right"/></el-form-item></div></el-form-item></template></div>
<el-alert v-if="demand" :title="quantityHint" :type="Number(form.quantity)>availableQuantity?'error':'info'" :closable="false" show-icon class="quantity-hint"/>
<div class="form-two"><el-form-item v-if="!demand" label="起运地区" prop="originCodes"><el-cascader v-model="form.originCodes" :options="cityOptions" filterable placeholder="选择省 / 市"/></el-form-item><el-form-item v-if="!demand" label="目的地区" prop="destinationCodes"><el-cascader v-model="form.destinationCodes" :options="cityOptions" filterable placeholder="选择省 / 市"/></el-form-item><el-form-item v-if="demand" label="起运详细地址" prop="originPoint"><PointPicker :model-value="form.originPoint" label="起运位置" :nodes="options.nodes||[]" :search-text="form.originAddress" :disabled="saving" @update:model-value="selectLocation('origin',$event)"/></el-form-item><el-form-item v-if="demand" label="目的详细地址" prop="destinationPoint"><PointPicker :model-value="form.destinationPoint" label="目的位置" :nodes="options.nodes||[]" :search-text="form.destinationAddress" :disabled="saving" @update:model-value="selectLocation('destination',$event)"/></el-form-item></div>
<template v-if="demand"><div class="form-two"><el-form-item label="计划发运时间" prop="departureAt"><el-date-picker v-model="form.departureAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" placeholder="选择未来发运时间" :disabled-date="disabledDepartureDate" :disabled-hours="disabledDepartureHours" :disabled-minutes="disabledDepartureMinutes" :disabled-seconds="disabledDepartureSeconds" :default-time="departureDefaultTime" :show-now="false" @visible-change="departureVisible"/></el-form-item><el-form-item label="要求到达时间" prop="arrivalAt"><el-date-picker v-model="form.arrivalAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" placeholder="选择到达时间"/></el-form-item></div><el-form-item label="运输方式偏好（不选表示不限）"><el-checkbox-group v-model="form.modeIds"><el-checkbox v-for="m in options.modes" :key="m.id" :value="m.id">{{m.label}}</el-checkbox></el-checkbox-group></el-form-item></template>
<template v-else><el-form-item label="适运粮种（不选表示不限）"><el-select v-model="form.grainIds" multiple><el-option v-for="g in options.grains" :key="g.id" :value="g.id" :label="g.label"/></el-select></el-form-item>
<div class="supply-pricing"><el-form-item label="装载形式" prop="loadingType"><el-radio-group v-model="form.loadingType"><el-radio-button value="BULK">散货</el-radio-button><el-radio-button value="CONTAINER">集装箱</el-radio-button></el-radio-group></el-form-item><div class="supply-price-fields"><el-form-item v-if="form.loadingType==='BULK'" label="散货报价（元/吨）" prop="bulkPrice"><el-input-number v-model="form.bulkPrice" :min=".01" :max="20000000" :precision="2" controls-position="right" placeholder="填写每吨报价"/></el-form-item><template v-else><el-form-item label="20GP 报价（元/箱）" prop="container20Price"><el-input-number v-model="form.container20Price" :min=".01" :max="20000000" :precision="2" controls-position="right" placeholder="填写 20GP 报价"/></el-form-item><el-form-item label="40GP 报价（元/箱）" prop="container40Price"><el-input-number v-model="form.container40Price" :min=".01" :max="20000000" :precision="2" controls-position="right" placeholder="填写 40GP 报价"/></el-form-item></template></div></div>
<el-form-item label="资源说明（选填）"><el-input v-model="form.resourceDescription" type="textarea" maxlength="500" placeholder="车型 / 车数 / 船型 / 班次等"/></el-form-item><el-form-item label="配套服务能力"><el-input v-model="form.capabilities" maxlength="300" placeholder="如装卸、仓储、防潮"/></el-form-item></template>
<h3>{{demand?'03':'02'}} · 联系与补充</h3><div class="form-two"><el-form-item label="联系人" prop="contact"><el-input v-model="form.contact" maxlength="40"/></el-form-item><el-form-item label="联系电话" prop="phone"><el-input v-model="form.phone" maxlength="30"/></el-form-item></div><el-form-item label="补充说明"><el-input v-model="form.notes" type="textarea" :rows="3" maxlength="2000" show-word-limit/></el-form-item><p class="form-hint">保存后可在详情中添加货物照片和业务附件。数量以吨计，保留 1 位小数。</p>
</el-form><template #footer><el-button @click="discard" :disabled="saving">取消</el-button><el-button type="primary" @click="save" :loading="saving">保存草稿</el-button></template></el-drawer>

<el-dialog v-model="orderOpen" top="3vh" title="选择交易订单明细" width="min(1100px, 94vw)" :close-on-click-modal="false"><p class="form-hint">仅展示当前企业的有效订单，选择后带入粮食品种、等级和提货地址。</p><el-form class="filter-form order-search" inline @submit.prevent="orderQuery.page=1;loadOrders()"><el-form-item><el-input v-model="orderQuery.q" aria-label="订单搜索" placeholder="交易订单号 / 粮食品种 / 提货地址" clearable/></el-form-item><el-form-item class="filter-actions"><el-button native-type="submit" type="primary" plain>查询订单</el-button></el-form-item></el-form><el-alert v-if="orderError" :title="orderError" type="error" :closable="false"><el-button @click="loadOrders">重试</el-button></el-alert><el-table v-else class="order-table" :data="orderRows" v-loading="orderLoading" empty-text="暂无有效交易订单，请联系平台导入"><el-table-column prop="tradeOrder.businessNo" label="交易订单号" min-width="175"/><el-table-column prop="grain.label" label="粮食品种" width="95"/><el-table-column label="资料状态" width="95"><template #default="{row}"><el-tag v-if="row.tradeOrder.sourceType==='INITIALIZATION'" type="warning" size="small">待核验</el-tag><span v-else>已录入</span></template></el-table-column><el-table-column prop="grainGrade" label="粮食等级" width="95"><template #default="{row}">{{row.grainGrade||'—'}}</template></el-table-column><el-table-column label="成交数量" width="120"><template #default="{row}">{{tonnes(row.quantity)}}吨</template></el-table-column><el-table-column label="剩余可运输" width="120"><template #default="{row}">{{tonnes(row.remainingQuantity)}}吨</template></el-table-column><el-table-column prop="pickupAddress" label="提货地址" min-width="260"><template #default="{row}">{{row.pickupAddress||'—'}}</template></el-table-column><el-table-column label="操作" width="80"><template #default="{row}"><el-button link type="primary" :disabled="row.remainingQuantity+(row.id===originalOrderId?originalQuantity:0)<.1" :title="'剩余可运输 '+tonnes(row.remainingQuantity)+' 吨'" @click="selectOrder(row)">选择</el-button></template></el-table-column></el-table><div class="order-pagination"><el-pagination v-model:current-page="orderQuery.page" :page-size="10" :total="orderTotal" layout="total, prev, pager, next" @current-change="loadOrders"/></div></el-dialog>

<el-drawer v-model="detailOpen" :title="name+'详情'" size="min(780px, 100vw)" @closed="closeDetail"><el-skeleton v-if="detailLoading" :rows="12" animated/><el-alert v-else-if="detailError" :title="detailError" type="error" :closable="false"/><template v-else-if="detail"><div class="detail-business-heading"><GrainImage :code="grainCode(detail)" :photo="photo(detail)"/><div><h2>{{demand?demandTitle(detail):supplyCompany(detail)}}</h2><p>{{detail.businessNo}} · {{detail.businessEntity.name}}</p></div><BusinessStatus :status="detail.status" :label="statusNames[detail.status]"/></div><div v-if="canWrite||demand&&auth.can('plan:solve')" class="detail-actions"><el-button v-if="demand&&detail.status!=='CANCELLED'&&auth.can('plan:solve')" @click="router.push({path:'/plans/solve',query:{demandId:detail.id}})">方案求解</el-button><template v-if="canWrite"><el-button v-if="editable(detail)" @click="edit(detail)">编辑</el-button><el-button v-if="canPublish&&['DRAFT',...(!demand?['PAUSED']:[])].includes(detail.status)" type="primary" @click="publish(detail)">发布</el-button><el-button v-if="detail.status==='PUBLISHED'" :disabled="saving||(demand&&detail.matchedKg>0)" :title="demand&&detail.matchedKg>0?'请先在匹配中取消承运确认':''" @click="action(detail,demand?'withdraw':'pause')">{{demand?'撤回发布':'暂停供给'}}</el-button><el-button v-if="demand&&['DRAFT','PUBLISHED'].includes(detail.status)" :disabled="saving||detail.matchedKg>0" @click="action(detail,'cancel')">取消需求</el-button><el-button v-if="!demand&&detail.status!=='EXPIRED'" :disabled="saving" @click="action(detail,'expire')">终止供给</el-button><el-button v-if="demand?detail.status==='DRAFT':detail.status!=='PUBLISHED'" type="danger" plain :disabled="saving" @click="action(detail,'delete')">删除</el-button></template></div>
<div class="detail-route"><div><small>起运地</small><strong>{{detail.originRegion}}</strong><p v-if="demand">{{detail.originAddress}}</p></div><Icon name="arrow"/><div><small>目的地</small><strong>{{detail.destinationRegion}}</strong><p v-if="demand">{{detail.destinationAddress}}</p></div></div>
<el-descriptions :column="2" border class="transport-description"><el-descriptions-item :label="demand?'运输数量':'可承运数量范围'"><b>{{demand?tonnes(detail.quantity)+' 吨':supplyRange(detail)}}</b></el-descriptions-item>
<template v-if="demand"><el-descriptions-item v-if="detail.orderItem?.tradeOrder.businessNo" label="交易订单">{{detail.orderItem?.tradeOrder.businessNo||'—'}}</el-descriptions-item><el-descriptions-item label="粮食 / 规格">{{detail.orderItem?.cargoName||detail.cargoName||detail.grain?.label}} / {{detail.orderItem?.specification||detail.specification||'—'}}</el-descriptions-item><el-descriptions-item label="计划发运">{{fullDate(detail.departureAt)}}</el-descriptions-item><el-descriptions-item label="要求到达">{{fullDate(detail.arrivalAt)}}</el-descriptions-item><el-descriptions-item label="方式偏好">{{detail.modes.map((m:any)=>m.mode.label).join('、')||'不限'}}</el-descriptions-item><el-descriptions-item label="装载形式">{{label(detail.loadingType)}}</el-descriptions-item></template>
<template v-else><el-descriptions-item label="运输企业" :span="2">{{supplyCompany(detail)}}</el-descriptions-item><el-descriptions-item label="运输方式">{{detail.mode.label}}</el-descriptions-item><el-descriptions-item label="适运粮种">{{detail.grains.map((g:any)=>g.grain.label).join('、')||'不限'}}</el-descriptions-item><el-descriptions-item label="装载形式">{{supplyLoading(detail)}}</el-descriptions-item><el-descriptions-item label="报价"><div v-for="price in supplyQuotes(detail)" :key="price">{{price}}</div></el-descriptions-item><el-descriptions-item label="资源说明" :span="2">{{detail.resourceDescription||'未填写'}}</el-descriptions-item><el-descriptions-item label="配套服务">{{detail.capabilities||'未填写'}}</el-descriptions-item></template>
<el-descriptions-item label="联系人">{{detail.contact||'未公开'}}</el-descriptions-item><el-descriptions-item label="联系电话">{{detail.phone||'未公开'}}</el-descriptions-item><el-descriptions-item label="补充说明" :span="2"><span class="preserve-lines">{{detail.notes||'无'}}</span></el-descriptions-item></el-descriptions>
<section class="detail-section"><h3>货物照片与附件</h3><div v-if="editable(detail)" class="file-tools"><el-select v-model="fileKind" aria-label="附件用途"><el-option label="业务附件" value="DOCUMENT"/><el-option label="货物照片" value="PHOTO"/></el-select><el-button @click="fileInput?.click()" :disabled="saving">上传附件</el-button><input ref="fileInput" type="file" accept="image/png,image/jpeg,image/webp,application/pdf" hidden @change="upload"/></div><p class="form-hint">支持 PNG、JPG、WebP、PDF，每个不超过 10MB，最多 10 个。货物照片优先用于列表展示。</p><div v-for="file in detail.files" :key="file.id" class="file-row"><button class="text-link" @click="download(file)">{{file.name}}</button><small>{{(file.size/1024).toFixed(0)}} KB · {{file.kind==='PHOTO'?'货物照片':'业务附件'}}</small><el-button v-if="editable(detail)" link type="danger" @click="removeFile(file)" :disabled="saving">移除</el-button></div><p v-if="!detail.files?.length" class="form-hint">暂无附件</p></section>
<section v-if="demand" class="detail-section"><h3>匹配进度：{{matchNames[detail.matchStage]||'未匹配'}}</h3><p>已落实 {{tonnes((detail.matchedKg||0)/1000)}} / {{tonnes(detail.quantity)}} 吨</p><h3>发布记录</h3><div v-for="p in detail.publications" :key="p.id" class="publication-card"><div><strong>{{label(p.mode)}}{{p.targetCarriers?.length?' · '+p.targetCarriers.map((c:any)=>c.name).join('、'):p.targetCarrier?' · '+p.targetCarrier.name:''}}</strong><el-tag size="small" type="info">{{statusNames[p.status]||p.status}}</el-tag></div><el-button v-if="auth.can('match:read')" link type="primary" @click="router.push({path:'/matches',query:{id:p.id}})">查看匹配与报价</el-button><p>{{p.businessNo}} · 截止 {{fullDate(p.deadline)}}</p><p>{{p.quoteType==='TOTAL'?'按总价报价':'按吨报价'}}</p><p v-if="p.notes" class="preserve-lines">{{p.notes}}</p></div><p v-if="!detail.publications.length" class="form-hint">尚未发布。{{detail.orderItemId?'草稿已占用订单可运输数量。':''}}</p></section>
<section class="detail-section"><h3>操作记录</h3><div v-for="entry in history" :key="entry.id" class="transport-history"><span class="status-dot"></span><strong>{{entry.action}}</strong><span>{{entry.userName}}</span><time>{{fullDate(entry.createdAt)}}</time></div></section>
</template></el-drawer>

<el-dialog v-model="publicationOpen" title="发布运输需求" width="min(580px, 94vw)" :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving"><el-alert v-if="publicationError" :title="publicationError" type="error" :closable="false" class="transport-alert"/><p class="form-hint">{{publicationRow?.name}} · {{tonnes(publicationRow?.quantity)}} 吨。发布后需撤回才能编辑。</p><el-form label-position="top" :disabled="saving"><el-form-item label="发布方式" required><el-radio-group v-model="publication.mode"><el-radio value="PUBLIC">公开发布</el-radio><el-radio value="DIRECTED">邀约议价</el-radio></el-radio-group></el-form-item><el-form-item v-if="publication.mode==='DIRECTED'" label="邀约物流运营商" required><el-select v-model="publication.targetCarrierIds" multiple filterable aria-label="邀约物流运营商（可多选）"><el-option v-for="c in options.carriers" :key="c.id" :value="c.id" :label="c.name"/></el-select></el-form-item><el-form-item label="响应截止时间" required><el-date-picker v-model="publication.deadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" placeholder="不得晚于计划发运时间"/></el-form-item><el-form-item label="报价口径"><el-radio-group v-model="publication.quoteType"><el-radio value="TOTAL">总价</el-radio><el-radio value="PER_TON">每吨单价</el-radio></el-radio-group></el-form-item><el-form-item label="发布说明"><el-input v-model="publication.notes" type="textarea" maxlength="1000"/></el-form-item></el-form><template #footer><el-button @click="publicationOpen=false" :disabled="saving">返回</el-button><el-button type="primary" @click="confirmPublish" :loading="saving">确认发布</el-button></template></el-dialog>
